[DOC-BUB-01] Bubble Sort - Bubble Sort Pseudocode with Early Termination
procedure bubbleSort(arr, n):
  for i from 0 to n - 2:
    swapped = false
    for j from 0 to n - i - 2:
      if arr[j] > arr[j + 1]:
        swap(arr[j], arr[j + 1])
        swapped = true
    if not swapped:
      break // Early exit: array is already sorted
  return arr

[DOC-STK-01] Stack Data Structure - Stack Operations Pseudocode
class Stack(capacity):
  items = array of size capacity
  top = -1

  function push(x):
    if top == capacity - 1:
      raise StackOverflowError
    top = top + 1
    items[top] = x

  function pop():
    if top == -1:
      raise StackUnderflowError
    val = items[top]
    top = top - 1
    return val

  function peek():
    if top == -1:
      raise StackUnderflowError
    return items[top]
